<template><view class="page detail-page safe-bottom"><view v-if="service.serviceId"><view class="detail-hero"><view class="detail-cover"><image v-if="service.imageUrl" :src="service.imageUrl" mode="aspectFill" /><uni-icons v-else type="home" size="54" color="#2e806d" /></view><text class="detail-category">{{ service.categoryName || '家政服务' }}</text><text class="detail-title">{{ service.serviceName }}</text><text class="detail-intro">{{ service.serviceIntro || '暂无服务简介' }}</text></view><view class="detail-price surface"><text class="price">¥{{ service.price }}</text><text v-if="service.originalPrice" class="original">¥{{ service.originalPrice }}</text><text class="unit">/{{ service.unitName || '次' }}</text><text class="reserve">已有 {{ service.reserveCount || 0 }} 人预约</text></view><view class="detail-section surface"><text class="section-title">服务说明</text><text class="detail-content">{{ stripHtml(service.detailContent) || '暂无服务说明' }}</text></view><view class="bottom-action"><view><text class="action-label">合计</text><text class="action-price">¥{{ service.price }}</text></view><button class="primary-button" @click="book">立即预约</button></view></view><view v-else class="empty-panel surface">{{ errorMessage || '服务不存在或已下架' }}</view></view></template>
<script setup>
import { onMounted, ref } from 'vue'; import uniIcons from '@dcloudio/uni-ui/lib/uni-icons/uni-icons.vue'; import { getService } from '@/api/service'; import { useAuthStore } from '@/stores/auth'
const authStore = useAuthStore(); const service = ref({}); const errorMessage = ref(''); onMounted(async () => { const id = getCurrentPages().at(-1)?.options?.id; try { const response = await getService(id); service.value = response?.data || response; uni.setNavigationBarTitle({ title: service.value.serviceName || '服务详情' }) } catch (e) { errorMessage.value = e.message || '服务加载失败' } })
function stripHtml (value) { return String(value || '').replace(/<[^>]+>/g, '').trim() }; function book () { const target = `/pages/booking/index?id=${service.value.serviceId}`; if (!authStore.isLoggedIn) return uni.navigateTo({ url: `/pages/login/index?redirect=${encodeURIComponent(target)}` }); uni.navigateTo({ url: target }) }
</script><style lang="scss" scoped>
.detail-page{padding-bottom:180rpx}.detail-hero{margin:-32rpx -32rpx 0;padding:48rpx 32rpx 40rpx;background:$app-primary-tint}.detail-cover{display:flex;align-items:center;justify-content:center;width:150rpx;height:150rpx;margin-bottom:28rpx;border-radius:28rpx;background:$app-primary-soft;box-shadow:0 12rpx 26rpx rgba(35,90,73,.1);overflow:hidden}.detail-cover image{width:100%;height:100%}.detail-category{display:block;color:$app-primary;font-size:23rpx;font-weight:600}.detail-title{display:block;margin-top:10rpx;color:$app-text;font-size:42rpx;font-weight:800}.detail-intro{display:block;margin-top:14rpx;color:$app-muted;font-size:26rpx;line-height:1.6}.detail-price{display:flex;align-items:baseline;margin-top:22rpx;padding:28rpx}.price,.action-price{color:$app-accent;font-size:42rpx;font-weight:800}.original{margin-left:14rpx;color:#aab8b2;font-size:24rpx;text-decoration:line-through}.unit{color:$app-muted;font-size:24rpx}.reserve{margin-left:auto;color:$app-muted;font-size:22rpx}.detail-section{margin-top:20rpx;padding:30rpx}.detail-content{display:block;margin-top:20rpx;color:$app-muted;font-size:27rpx;line-height:1.8}.bottom-action{position:fixed;right:0;bottom:0;left:0;z-index:10;display:flex;align-items:center;justify-content:space-between;padding:20rpx 32rpx calc(20rpx + env(safe-area-inset-bottom));background:#fff;border-top:1rpx solid $app-border}.action-label{display:block;color:$app-muted;font-size:22rpx}.action-price{display:block;margin-top:2rpx;font-size:34rpx}.bottom-action .primary-button{width:280rpx;line-height:78rpx;font-size:28rpx}
</style>
